// Author: MiYu. Source-priced building unsummon checks real orders, worker independence and resource/lifetime consumers.
#include "session.h"
#include "setup.h"
#include <bit>
#include <iostream>
using namespace war3;
int wmain(int argc,wchar_t** argv){
    try{
        if(argc<3 || argc>4)throw std::runtime_error("Usage: war3_unsummon_tests <data-root> <fixture> [lifecycle|boundaries|ai]");std::wstring mode=argc>3?argv[3]:L"lifecycle";if(mode!=L"lifecycle" && mode!=L"boundaries" && mode!=L"ai")throw std::runtime_error("Unknown unsummon check mode");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());setup.control(1,SlotControl::ComputerNormal);session.applySetup(setup);session.startMain();auto& vm=session.runtime();auto& ai=*session.ais()[0]->runtime;auto call=[](jass::Runtime& runtime,const char* name,std::initializer_list<jass::Value> args){return runtime.invoke(name,{args.begin(),args.size()});};auto require=[](bool value,const char* message){if(!value)throw std::runtime_error(message);};auto caster=vm.global("caster"),building=vm.global("building"),hostile=vm.global("enemy_building");auto ability=ObjectData::code("Auns");auto p0=call(vm,"Player",{vm.integer(0)}),p1=call(vm,"Player",{vm.integer(1)});auto before=session.config().players[0].states;auto state=session.units().at(building.bits);auto count=session.units().size();
        if(mode==L"ai"){
            require(call(ai,"GetBuilding",{ai.handle("player",p0.bits)}).bits==building.bits,"AI own-building lookup returned an enemy or no building");call(ai,"Unsummon",{ai.handle("unit",hostile.bits)});require(!session.units().at(hostile.bits)->unsummon,"AI unsummoned an enemy building");ai.start("UnsummonAll");session.advance(1);require(state->unsummon.has_value() && session.units().at(caster.bits)->x.bits()==jass::Real::fromInteger(-2048).bits(),"Original AI did not use its existing remote caster");session.advance(12);require(!session.units().contains(building.bits) && session.units().size()==count-1 && call(ai,"GetBuilding",{ai.handle("player",p0.bits)}).bits==0,"Original UnsummonAll did not finish without creating units");std::cout<<"PASS original_ai_unsummon_all\n";
        }else{
            auto buttons=session.abilityCommands(caster.bits,0);require(std::any_of(buttons.begin(),buttons.end(),[&](auto& b){return b.type==ability && b.action==CommandAction::CastSpell && b.enabled && b.hotkey=="U" && b.icon.find("BTNUnsummonBuilding")!=std::string::npos;}),"Original unsummon art/hotkey did not reach the ability command UI");require(!call(vm,"IssueTargetOrder",{caster,vm.string("unsummon"),hostile}).bits,"Unsummon accepted an enemy building");require(call(vm,"IssueTargetOrder",{caster,vm.string("unsummon"),building}).bits,"Source unsummon order was rejected");session.advance(1);require(state->unsummon.has_value() && std::bit_cast<float>(state->life.bits())<550 && session.config().players[0].states.at(1)>1000 && session.commands(building.bits,0).empty(),"Unsummon did not enter live decay/refund and command isolation");require(!call(vm,"IssueTargetOrder",{caster,vm.string("unsummon"),building}).bits,"Duplicate unsummon was accepted");
            if(mode==L"lifecycle"){
                call(vm,"KillUnit",{caster});session.advance(12);auto& after=session.config().players[0].states;require(!session.units().contains(building.bits) && session.units().size()==count-1 && after.at(1)==1075 && after.at(2)==1025 && after.at(4)==before.at(4)-10,"Building unsummon did not retain source refund/population after caster death");require(session.statistics()[0].goldMined==0 && session.statistics()[0].lumberMined==0,"Refund was counted as mining income");std::cout<<"PASS source_unsummon_refund_and_lifecycle gold=75 lumber=25 game_dll_loaded=false\n";
            }else{
                call(vm,"PauseUnit",{building,vm.boolean(true)});auto life=state->life.bits();auto gold=session.config().players[0].states.at(1);session.advance(1);require(state->life.bits()==life && session.config().players[0].states.at(1)==gold,"Paused unsummon continued to drain/refund");call(vm,"SetUnitOwner",{building,p1,vm.boolean(false)});call(vm,"PauseUnit",{building,vm.boolean(false)});require(!state->unsummon,"Ownership transfer retained a paid unsummon job");session.advance(1);require(state->life.bits()==life && session.config().players[0].states.at(1)==gold && session.units().contains(building.bits),"Ownership transfer continued old-owner deconstruction or refund");std::cout<<"PASS duplicate_enemy_pause_and_transfer_boundaries\n";
            }
        }
        if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"RESULT passed=1 failed=0\n";return 0;
    }catch(const std::exception& error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}
}
